import json,subprocess,time,datetime,sys
from pathlib import Path
r=Path(__file__).resolve().parent
query='num_gpus=2 gpu_ram>=10 reliability>0.98 rentable=True rented=False inet_down>150 disk_space>40 cuda_max_good>=12.4 dph_total<=0.33'
p=subprocess.run(['vastai','search','offers',query,'--order','dph_total','--limit','40','--raw'],capture_output=True,text=True,timeout=60);assert p.returncode==0;rows=json.loads(p.stdout);(r/'immediate-alternative-quotes.json').write_text(json.dumps(rows,indent=2))
