if not choices:print(json.dumps({'allocated':False,'reason':'no qualified offers'}));sys.exit(0)
o=min(choices,key=lambda x:(0 if x['machine_id'] in [139287,51793] else 1,x['dph_total']));plan=json.loads((r/'replacement-plan.json').read_text());plan.update(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),offer_id=o['id'],machine_id=o['machine_id'],gpu_name=o['gpu_name'],num_gpus=2,quote_hourly_usd=o['dph_total'],source_commit='3edc309',image_cache_known=False,previous_P7R_reported_spend_usd=.008,selection_rule=query,alternative_attempt_number=1)
(r/'selected-alternative-plan.json').write_text(json.dumps(plan,indent=2));print(json.dumps({'selected':{k:o.get(k) for k in ['id','machine_id','gpu_name','num_gpus','dph_total','cpu_cores_effective','cpu_ram']}}),flush=True)
p=subprocess.run(['vastai','create','instance',str(o['id']),'--image',plan['image'],'--disk','40','--ssh','--direct','--label','cyp-private-p7r-alternative-20261026','--cancel-unavail','--raw'],capture_output=True,text=True,timeout=120);(r/'actual-alternative-create-stdout.txt').write_text(p.stdout);(r/'actual-alternative-create-stderr.txt').write_text(p.stderr)
